#[cfg(test)]
mod tests {
    use super::*;

    fn norm(groups: Vec<Vec<String>>) -> Vec<Vec<String>> {
        let mut out: Vec<Vec<String>> = groups
            .into_iter()
            .map(|mut g| {
                g.sort();
                g
            })
            .collect();
        out.sort();
        out
    }

    fn owned(groups: &[&[&str]]) -> Vec<Vec<String>> {
        groups.iter().map(|g| g.iter().map(|s| s.to_string()).collect()).collect()
    }

    #[test]
    fn basic() {
        let out = group_anagrams(&["listen", "pots", "silent", "stop", "tops", "cat"]);
        assert_eq!(
            norm(out),
            norm(owned(&[&["listen", "silent"], &["pots", "stop", "tops"], &["cat"]]))
        );
    }

    #[test]
    fn empty_list() {
        assert!(group_anagrams(&[]).is_empty());
    }

    #[test]
    fn empty_strings() {
        assert_eq!(norm(group_anagrams(&["", "", "a"])), norm(owned(&[&["", ""], &["a"]])));
    }

    #[test]
    fn no_anagrams() {
        assert_eq!(
            norm(group_anagrams(&["ab", "cd", "ef"])),
            norm(owned(&[&["ab"], &["cd"], &["ef"]]))
        );
    }

    #[test]
    fn same_letters_different_counts() {
        assert_eq!(
            norm(group_anagrams(&["aab", "abb", "baa"])),
            norm(owned(&[&["aab", "baa"], &["abb"]]))
        );
    }
}
